@import "tailwindcss";

/* TrustRAG Enterprise Security Dashboard Theme - Dark Mode */
@layer base {
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: #0A0C10;
    color: #E2E2E8;
    -webkit-font-smoothing: antialiased;
  }

  code, .mono {
    font-family: 'JetBrains Mono', 'SF Mono', 'Fira Code', 'Fira Mono', Menlo, Consolas, monospace;
  }
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: #1a1c20;
}
::-webkit-scrollbar-thumb {
  background: #414752;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #8b919d;
}

/* TrustRAG Color Variables */
:root {
  --surface-dim: #111318;
  --surface-container: #1e2024;
  --surface-container-low: #1a1c20;
  --surface-container-high: #282a2e;
  --surface-variant: #333539;
  --on-surface: #e2e2e8;
  --on-surface-variant: #c0c7d4;
  --primary: #a2c9ff;
  --primary-container: #58a6ff;
  --secondary: #67df70;
  --secondary-container: #27a640;
  --tertiary: #fabc45;
  --tertiary-container: #d29922;
  --error: #ffb4ab;
  --outline: #8b919d;
  --outline-variant: #414752;
}

/* Material Symbols */
.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
}

/* Dark theme utility classes */
.bg-surface-dim { background-color: var(--surface-dim); }
.bg-surface-container { background-color: var(--surface-container); }
.bg-surface-container-low { background-color: var(--surface-container-low); }
.bg-surface-container-high { background-color: var(--surface-container-high); }
.bg-surface-variant { background-color: var(--surface-variant); }
.text-on-surface { color: var(--on-surface); }
.text-on-surface-variant { color: var(--on-surface-variant); }
.text-primary { color: var(--primary); }
.bg-primary { background-color: var(--primary); }
.text-secondary { color: var(--secondary); }
.bg-secondary { background-color: var(--secondary); }
.text-tertiary { color: var(--tertiary); }
.text-error { color: var(--error); }
.border-outline-variant { border-color: var(--outline-variant); }

/* Pipeline connector */
.pipeline-connector {
  position: relative;
}
.pipeline-connector::after {
  content: '';
  position: absolute;
  top: 50%;
  right: -24px;
  width: 16px;
  height: 1px;
  background-color: var(--outline-variant);
}

