import { NavLink } from 'react-router-dom';

const navItems = [
  { to: '/', label: 'DASHBOARD', icon: 'dashboard' },
  { to: '/documents', label: 'DOCUMENTS', icon: 'description' },
  { to: '/chat', label: 'RAG CHAT', icon: 'chat_bubble' },
  { to: '/knowledge', label: 'KNOWLEDGE BASE', icon: 'database' },
  { to: '/status', label: 'SYSTEM STATUS', icon: 'analytics' },
];

export default function Sidebar() {
  return (
    <aside className="fixed left-0 top-0 h-full w-[260px] bg-[#1e2024] border-r border-[#414752] flex flex-col py-4 z-50">
      {/* Logo */}
      <div className="px-6 mb-10">
        <h1 className="text-[24px] leading-[32px] font-bold text-[#a2c9ff]">
          TrustRAG
        </h1>
        <p className="text-[12px] leading-[16px] text-[#c0c7d4] opacity-70 mt-0.5">
          Enterprise AI v1.2.0
        </p>
      </div>

      {/* Navigation */}
      <nav className="flex-1 space-y-1">
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            end={item.to === '/'}
            className={({ isActive }) =>
              `flex items-center px-6 py-3 transition-all duration-150 ease-in-out ${
                isActive
                  ? 'bg-[#333539] text-[#a2c9ff] border-l-2 border-[#a2c9ff]'
                  : 'text-[#c0c7d4] font-medium hover:bg-[#333539] hover:text-[#e2e2e8]'
              }`
            }
          >
            <span className="material-symbols-outlined mr-3">{item.icon}</span>
            <span className="text-[11px] leading-[16px] tracking-[0.05em] font-bold uppercase">
              {item.label}
            </span>
          </NavLink>
        ))}
      </nav>

      {/* Footer */}
      <div className="px-6 pt-4 border-t border-[#414752] space-y-3">
        <div className="flex items-center text-[#c0c7d4]">
          <span className="material-symbols-outlined text-[18px] mr-2">history</span>
          <span className="text-[12px] leading-[16px]">Versioning</span>
        </div>
        <div className="flex items-center text-[#67df70]">
          <span className="material-symbols-outlined text-[18px] mr-2">check_circle</span>
          <span className="text-[12px] leading-[16px]">Status: Healthy</span>
        </div>
      </div>
    </aside>
  );
}

