interface CardProps {
  title: string;
  value: string | number;
  subtitle?: string;
  icon?: string;
  status?: 'online' | 'offline' | 'warning';
}

export default function Card({ title, value, subtitle, icon, status }: CardProps) {
  const statusColor = {
    online: 'bg-[#67df70]',
    offline: 'bg-[#ffb4ab]',
    warning: 'bg-[#fabc45]',
  };

  return (
    <div className="bg-[#1e2024] border border-[#414752] p-4 hover:bg-[#282a2e] transition-colors">
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <p className="text-[11px] leading-[16px] tracking-[0.05em] font-bold text-[#c0c7d4] uppercase">
            {title}
          </p>
          <p className="text-[24px] leading-[32px] font-semibold text-[#e2e2e8] mt-2">
            {value}
          </p>
          {subtitle && (
            <p className="text-[12px] leading-[16px] text-[#8b919d] mt-1">{subtitle}</p>
          )}
        </div>
        {icon && (
          <span className="material-symbols-outlined text-[#c0c7d4] text-[24px]">{icon}</span>
        )}
        {status && (
          <span className={`w-2.5 h-2.5 rounded-full ${statusColor[status]} mt-1.5`} />
        )}
      </div>
    </div>
  );
}

