interface StatusBadgeProps {
  status: string;
  size?: 'sm' | 'md';
}

const statusStyles: Record<string, { bg: string; text: string; dot: string }> = {
  online: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  ready: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  connected: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  operational: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  verified: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  processed: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  indexed: { bg: 'bg-[#27a640]/20', text: 'text-[#67df70]', dot: 'bg-[#67df70]' },
  error: { bg: 'bg-[#93000a]/20', text: 'text-[#ffb4ab]', dot: 'bg-[#ffb4ab]' },
  offline: { bg: 'bg-[#93000a]/20', text: 'text-[#ffb4ab]', dot: 'bg-[#ffb4ab]' },
  failed: { bg: 'bg-[#93000a]/20', text: 'text-[#ffb4ab]', dot: 'bg-[#ffb4ab]' },
  degraded: { bg: 'bg-[#d29922]/20', text: 'text-[#fabc45]', dot: 'bg-[#fabc45]' },
  warning: { bg: 'bg-[#d29922]/20', text: 'text-[#fabc45]', dot: 'bg-[#fabc45]' },
};

export default function StatusBadge({ status, size = 'sm' }: StatusBadgeProps) {
  const key = status.toLowerCase();
  const style = statusStyles[key] || { bg: 'bg-[#333539]', text: 'text-[#c0c7d4]', dot: 'bg-[#8b919d]' };
  const sizeClasses = size === 'sm' ? 'text-[12px] leading-[16px] px-2 py-0.5' : 'text-[14px] leading-[20px] px-3 py-1';

  return (
    <span className={`inline-flex items-center gap-1.5 rounded font-medium ${style.bg} ${style.text} ${sizeClasses}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${style.dot}`} />
      {status}
    </span>
  );
}

