import { useState, useRef, type DragEvent } from 'react';

interface FileUploadProps {
  onUpload: (file: File) => Promise<void>;
  disabled?: boolean;
}

export default function FileUpload({ onUpload, disabled }: FileUploadProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = async (file: File) => {
    const ext = file.name.split('.').pop()?.toLowerCase();
    if (!['pdf', 'docx', 'txt'].includes(ext || '')) {
      setError('Unsupported file type. Allowed: PDF, DOCX, TXT');
      return;
    }
    if (file.size > 50 * 1024 * 1024) {
      setError('File too large. Maximum size: 50MB');
      return;
    }
    setError(null);
    setIsUploading(true);
    try {
      await onUpload(file);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setIsUploading(false);
    }
  };

  const handleDrop = (e: DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  };

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  return (
    <div>
      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={() => setIsDragging(false)}
        onClick={() => inputRef.current?.click()}
        className={`border-2 border-dashed rounded p-8 text-center cursor-pointer transition-colors ${
          isDragging
            ? 'border-[#a2c9ff] bg-[#a2c9ff]/10'
            : 'border-[#414752] hover:border-[#8b919d] hover:bg-[#333539]'
        } ${disabled ? 'opacity-50 pointer-events-none' : ''}`}
      >
        <input
          ref={inputRef}
          type="file"
          accept=".pdf,.docx,.txt"
          className="hidden"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) handleFile(file);
            e.target.value = '';
          }}
        />
        {isUploading ? (
          <div className="flex flex-col items-center gap-2">
            <div className="w-8 h-8 border-2 border-[#a2c9ff] border-t-transparent rounded-full animate-spin" />
            <p className="text-[14px] leading-[20px] text-[#c0c7d4]">Uploading and indexing...</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-3">
            <span className="material-symbols-outlined text-[48px] text-[#a2c9ff]">cloud_upload</span>
            <div>
              <p className="text-[18px] leading-[24px] font-semibold text-[#e2e2e8]">
                Upload Knowledge
              </p>
              <p className="text-[14px] leading-[20px] text-[#c0c7d4] mt-2">
                Drag and drop a PDF here or <span className="text-[#a2c9ff] underline">Browse Files</span>
              </p>
              <p className="text-[12px] leading-[16px] text-[#8b919d] mt-2 uppercase tracking-wider">
                MAX 100MB PER FILE
              </p>
            </div>
          </div>
        )}
      </div>
      {error && (
        <div className="mt-3 px-4 py-3 bg-[#93000a]/20 border border-[#ffb4ab] rounded text-[14px] leading-[20px] text-[#ffb4ab]">
          {error}
        </div>
      )}
    </div>
  );
}

