import { useState, useRef, useEffect } from 'react';
import { api } from '../services/api';
import type { ChatMessage, SourceChunk } from '../types';

export default function Chat() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const question = input.trim();
    if (!question || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: question,
      timestamp: new Date(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await api.query(question);
      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.answer,
        sources: response.sources,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err) {
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `Error: ${err instanceof Error ? err.message : 'Failed to get response'}. Please ensure the backend is running.`,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  return (
    <div className="flex h-[calc(100vh-4rem)]">
      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <header className="flex justify-between items-center w-full px-6 h-16 bg-[#111318] border-b border-[#414752] -ml-6 -mt-6 mb-6">
          <div className="flex items-center space-x-4">
            <span className="text-[18px] leading-[24px] font-semibold text-[#e2e2e8]">
              RAG Chat Interface
            </span>
            <span className="w-[1px] h-6 bg-[#414752]"></span>
            <div className="flex items-center space-x-2">
              <span className="w-2 h-2 rounded-full bg-[#67df70] shadow-[0_0_8px_rgba(103,223,112,0.6)]"></span>
              <span className="text-[14px] leading-[20px] font-medium text-[#67df70]">ONLINE</span>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <button className="material-symbols-outlined text-[#c0c7d4] hover:text-[#a2c9ff] transition-colors">dns</button>
            <button className="material-symbols-outlined text-[#c0c7d4] hover:text-[#a2c9ff] transition-colors">memory</button>
            <button className="material-symbols-outlined text-[#c0c7d4] hover:text-[#a2c9ff] transition-colors">person</button>
          </div>
        </header>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto mb-4">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-[#c0c7d4]">
              <span className="material-symbols-outlined text-6xl mb-4">chat</span>
              <p className="font-medium text-[18px]">Ask a question to get started</p>
              <p className="text-[14px] mt-2">The RAG pipeline will search your documents for relevant context</p>
            </div>
          ) : (
            <div className="space-y-6">
              {messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] ${msg.role === 'user' ? 'order-2' : 'order-1'}`}>
                    {/* Message header */}
                    <div className="flex items-center space-x-2 mb-2">
                      {msg.role === 'assistant' && (
                        <span className="material-symbols-outlined text-[#a2c9ff]">smart_toy</span>
                      )}
                      <span className="text-[14px] leading-[20px] font-medium text-[#e2e2e8]">
                        {msg.role === 'user' ? 'SEC_OPERATOR_04' : 'TrustRAG CORE'}
                      </span>
                      <span className="text-[12px] leading-[16px] text-[#c0c7d4]">
                        {msg.timestamp.toLocaleTimeString()}
                      </span>
                    </div>

                    {/* Message bubble */}
                    <div className={`rounded px-4 py-3 ${
                      msg.role === 'user'
                        ? 'bg-[#333539] text-[#e2e2e8] border border-[#414752]'
                        : 'bg-[#1e2024] text-[#e2e2e8] border border-[#414752]'
                    }`}>
                      <p className="text-[14px] leading-[20px] whitespace-pre-wrap">{msg.content}</p>
                    </div>

                    {/* Sources (only for assistant messages) */}
                    {msg.role === 'assistant' && msg.sources && msg.sources.length > 0 && (
                      <SourcesPanel sources={msg.sources} />
                    )}

                    {/* Action buttons for assistant messages */}
                    {msg.role === 'assistant' && (
                      <div className="flex items-center space-x-4 mt-3">
                        <button className="flex items-center space-x-2 text-[14px] text-[#c0c7d4] hover:text-[#a2c9ff]">
                          <span className="material-symbols-outlined text-[18px]">thumb_up</span>
                          <span>Helpful</span>
                        </button>
                        <button className="flex items-center space-x-2 text-[14px] text-[#c0c7d4] hover:text-[#a2c9ff]">
                          <span className="material-symbols-outlined text-[18px]">thumb_down</span>
                          <span>Inaccurate</span>
                        </button>
                        <button className="flex items-center space-x-2 text-[14px] text-[#c0c7d4] hover:text-[#a2c9ff]">
                          <span className="material-symbols-outlined text-[18px]">content_copy</span>
                          <span>Copy</span>
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-[#1e2024] border border-[#414752] rounded px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className="w-2 h-2 bg-[#a2c9ff] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                      <div className="w-2 h-2 bg-[#a2c9ff] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                      <div className="w-2 h-2 bg-[#a2c9ff] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>

        {/* Input Area */}
        <form onSubmit={handleSubmit} className="flex gap-3">
          <div className="flex-1 relative">
            <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-[#c0c7d4]">
              attach_file
            </span>
            <textarea
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ask TrustRAG..."
              rows={1}
              className="w-full resize-none rounded bg-[#1e2024] border border-[#414752] pl-12 pr-4 py-3 text-[14px] text-[#e2e2e8] placeholder-[#8b919d] focus:outline-none focus:border-[#a2c9ff]"
              disabled={isLoading}
            />
          </div>
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className="flex items-center space-x-2 bg-[#a2c9ff] hover:bg-[#a2c9ff]/90 text-[#00315c] px-6 py-3 rounded font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <span>SEND</span>
            <span className="material-symbols-outlined">send</span>
          </button>
        </form>

        {/* Footer */}
        <div className="flex items-center justify-center space-x-6 mt-4 text-[12px] leading-[16px] text-[#8b919d]">
          <span>CONTEXT WINDOW: 32K TOKENS</span>
          <span>MODEL: GPT-4-SEC-ENHANCED</span>
        </div>
      </div>

      {/* Sources Sidebar */}
      <div className="w-[350px] ml-6 border-l border-[#414752] pl-6 overflow-y-auto">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-2">
            <span className="material-symbols-outlined text-[#a2c9ff]">source</span>
            <span className="text-[18px] leading-[24px] font-semibold text-[#e2e2e8]">Sources</span>
          </div>
          <span className="text-[12px] leading-[16px] text-[#c0c7d4] bg-[#333539] px-2 py-1 rounded">
            {messages.length > 0 && messages[messages.length - 1].sources?.length || 0} Retrieved
          </span>
        </div>

        {/* Source Cards */}
        <div className="space-y-4">
          <div className="bg-[#1e2024] border border-[#414752] p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-2">
                <span className="material-symbols-outlined text-[#a2c9ff]">description</span>
                <span className="text-[14px] leading-[20px] font-medium text-[#e2e2e8]">NIST_SP_800_53...</span>
              </div>
              <div className="text-right">
                <span className="text-[14px] leading-[20px] font-medium text-[#67df70]">0.87 SIM</span>
                <p className="text-[12px] leading-[16px] text-[#c0c7d4]">Page 112</p>
              </div>
            </div>
            <p className="text-[14px] leading-[20px] text-[#c0c7d4] font-mono">
              "AC-1: The organization develops, documents, and disseminates access control policies that address purpose, scope, roles, responsibilities..."
            </p>
          </div>

          <div className="bg-[#1e2024] border border-[#414752] p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-2">
                <span className="material-symbols-outlined text-[#a2c9ff]">description</span>
                <span className="text-[14px] leading-[20px] font-medium text-[#e2e2e8]">Security_Polic...</span>
              </div>
              <div className="text-right">
                <span className="text-[14px] leading-[20px] font-medium text-[#67df70]">0.82 SIM</span>
                <p className="text-[12px] leading-[16px] text-[#c0c7d4]">Page 4</p>
              </div>
            </div>
            <p className="text-[14px] leading-[20px] text-[#c0c7d4] font-mono">
              "All employees must utilize MFA for accessing internal databases. Role-based access control (RBAC) should be audited quarterly..."
            </p>
          </div>

          <div className="bg-[#1e2024] border border-[#414752] p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-2">
                <span className="material-symbols-outlined text-[#a2c9ff]">description</span>
                <span className="text-[14px] leading-[20px] font-medium text-[#e2e2e8]">Compliance_Fra...</span>
              </div>
              <div className="text-right">
                <span className="text-[14px] leading-[20px] font-medium text-[#67df70]">0.78 SIM</span>
                <p className="text-[12px] leading-[16px] text-[#c0c7d4]">Node ID: 8821</p>
              </div>
            </div>
            <p className="text-[14px] leading-[20px] text-[#c0c7d4] font-mono">
              "IA-2: Identification..."
            </p>
          </div>
        </div>

        {/* Knowledge Visualization */}
        <div className="mt-6">
          <h4 className="text-[11px] leading-[16px] tracking-[0.05em] font-bold text-[#c0c7d4] uppercase mb-4">
            KNOWLEDGE VISUALIZATION
          </h4>
          <div className="bg-[#1e2024] border border-[#414752] p-4 h-[200px] flex items-center justify-center">
            <div className="text-center">
              <span className="material-symbols-outlined text-4xl text-[#414752]">hub</span>
              <p className="text-[12px] leading-[16px] text-[#8b919d] mt-2">SIMILARITY CLUSTER MAP</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function SourcesPanel({ sources }: { sources: SourceChunk[] }) {
  return (
    <div className="mt-3 space-y-2">
      {sources.map((src) => (
        <div key={src.chunk_id} className="bg-[#111318] border border-[#414752] rounded p-3">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center space-x-2">
              <span className="material-symbols-outlined text-[#a2c9ff] text-[16px]">description</span>
              <span className="text-[12px] leading-[16px] font-medium text-[#e2e2e8]">{src.document_id}</span>
            </div>
            <span className="text-[12px] leading-[16px] text-[#c0c7d4]">Page {src.page}</span>
          </div>
          <p className="text-[12px] leading-[16px] text-[#c0c7d4] font-mono">
            "{src.text_preview}"
          </p>
          <div className="flex items-center justify-end mt-2">
            <span className="text-[12px] leading-[16px] text-[#67df70]">
              {src.score.toFixed(2)} SIM
            </span>
          </div>
        </div>
      ))}
    </div>
  );
}

