            <button className="material-symbols-outlined text-[#c0c7d4] hover:text-[#a2c9ff] transition-colors">memory</button>
            <button className="material-symbols-outlined text-[#c0c7d4] hover:text-[#a2c9ff] transition-colors">person</button>
          </div>
        </div>
      </header>

      {/* Page Title */}
      <div className="mb-8">
        <h1 className="text-[24px] leading-[32px] font-semibold text-[#e2e2e8]">Knowledge Base</h1>
        <p className="text-[14px] leading-[20px] text-[#c0c7d4] mt-1">
          View all indexed documents and their chunk data.
        </p>
      </div>

      <div className="bg-[#1e2024] border border-[#414752]">
        {/* Table Header */}
        <div className="grid grid-cols-12 gap-4 px-6 py-3 border-b border-[#414752] text-[11px] leading-[16px] tracking-[0.05em] font-bold text-[#c0c7d4] uppercase">
          <div className="col-span-4">Document</div>
          <div className="col-span-2">Document ID</div>
          <div className="col-span-1 text-center">Pages</div>
          <div className="col-span-1 text-center">Chunks</div>
          <div className="col-span-2">Uploaded</div>
          <div className="col-span-2">SHA-256</div>
        </div>

        {loading ? (
          <div className="p-8 text-center text-[#c0c7d4]">Loading knowledge base...</div>
        ) : error ? (
          <div className="p-8 text-center text-[#ffb4ab]">{error}</div>
        ) : !data?.documents.length ? (
          <div className="p-8 text-center text-[#c0c7d4]">
            No documents in the knowledge base. Upload documents from the Documents page.
          </div>
        ) : (
          <div className="divide-y divide-[#414752]">
            {data.documents.map((doc) => (
              <DocumentRow
                key={doc.filename}
                doc={doc}
                expanded={expandedDoc === doc.filename}
                onToggle={() => setExpandedDoc(expandedDoc === doc.filename ? null : doc.filename)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Summary */}
      {data && data.documents.length > 0 && (
        <div className="mt-4 text-[14px] leading-[20px] text-[#c0c7d4]">
          Total: {data.count} documents indexed
        </div>
      )}
    </div>
  );
}

function DocumentRow({ doc, expanded, onToggle }: { doc: DocumentInfo; expanded: boolean; onToggle: () => void }) {
  return (
    <div>
      <div
        onClick={onToggle}
        className="grid grid-cols-12 gap-4 px-6 py-4 hover:bg-[#333539] cursor-pointer transition-colors items-center"
      >
        <div className="col-span-4 flex items-center gap-3">
          <span className={`material-symbols-outlined text-[16px] transition-transform ${expanded ? 'rotate-90' : ''} text-[#c0c7d4]`}>chevron_right</span>
          <span className="material-symbols-outlined text-[#a2c9ff]">description</span>
          <span className="text-[14px] leading-[20px] font-medium text-[#e2e2e8] truncate">{doc.filename}</span>
        </div>
        <div className="col-span-2 text-[12px] leading-[16px] text-[#c0c7d4] font-mono truncate">
          {doc.document_id || '—'}
