          {doc.total_pages ?? '—'}
        </div>
        <div className="col-span-1 text-center text-[14px] leading-[20px] font-medium text-[#c0c7d4]">
          {doc.total_chunks ?? '—'}
        </div>
        <div className="col-span-2 text-[12px] leading-[16px] text-[#c0c7d4]">
          {doc.uploaded_at ? new Date(doc.uploaded_at).toLocaleDateString() : '—'}
        </div>
        <div className="col-span-2 text-[12px] leading-[16px] text-[#8b919d] font-mono truncate">
          {doc.sha256 ? `${doc.sha256.substring(0, 12)}...` : '—'}
        </div>
      </div>

      {/* Expanded Details */}
      {expanded && (
        <div className="px-6 pb-4 bg-[#111318] border-t border-[#414752]">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 py-4">
            <DetailItem label="Document ID" value={doc.document_id || '—'} />
            <DetailItem label="Filename" value={doc.filename} />
            <DetailItem label="Pages" value={String(doc.total_pages ?? '—')} />
            <DetailItem label="Chunks" value={String(doc.total_chunks ?? '—')} />
            <DetailItem label="Characters" value={doc.total_chars ? doc.total_chars.toLocaleString() : '—'} />
            <DetailItem label="File Size" value={`${(doc.size_bytes / 1024).toFixed(1)} KB`} />
            <DetailItem label="Uploaded By" value={doc.uploaded_by || '—'} />
            <DetailItem label="Status" value={doc.status || '—'} />
          </div>
          {doc.sha256 && (
            <div className="mt-2">
              <p className="text-[12px] leading-[16px] text-[#8b919d] mb-1">SHA-256 Hash</p>
              <p className="text-[12px] leading-[16px] font-mono text-[#c0c7d4] bg-[#1e2024] rounded border border-[#414752] p-2 break-all">
                {doc.sha256}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function DetailItem({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-[12px] leading-[16px] text-[#8b919d]">{label}</p>
      <p className="text-[14px] leading-[20px] text-[#e2e2e8] font-medium">{value}</p>
    </div>
  );
}

